<?php
$editing=isset($shipment);$error='';$customers=db()->query('SELECT id,name,code FROM customers ORDER BY name')->fetchAll();
if($editing&&!isset($items)){$q=db()->prepare('SELECT * FROM shipment_items WHERE shipment_id=? ORDER BY id');$q->execute([$shipment['id']]);$items=$q->fetchAll();}
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    $data=['customer_id'=>(int)($_POST['customer_id']??0),'brand_name'=>trim($_POST['brand_name']??''),'jtr_number'=>trim($_POST['jtr_number']??''),'weight'=>trim($_POST['weight']??''),'price'=>trim($_POST['price']??''),'shipment_date'=>$_POST['shipment_date']??'','status'=>$_POST['status']??'','notes'=>trim($_POST['notes']??'')];
    if(!$data['customer_id']||!$data['jtr_number']||!is_numeric($data['weight'])||(float)$data['weight']<0||($data['price']!==''&&(!is_numeric($data['price'])||(float)$data['price']<0))||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$data['shipment_date'])||!valid_status($data['status']))$error='Complete all required fields with valid values.';
    else try{
        $data['price']=$data['price']===''?null:$data['price'];
        db()->beginTransaction();
        if($editing){$s=db()->prepare('UPDATE shipments SET customer_id=?,brand_name=?,jtr_number=?,weight=?,price=?,shipment_date=?,status=?,notes=? WHERE id=?');$s->execute([...array_values($data),$shipment['id']]);$shipmentId=$shipment['id'];db()->prepare('DELETE FROM shipment_items WHERE shipment_id=?')->execute([$shipmentId]);}
        else{$s=db()->prepare('INSERT INTO shipments(customer_id,brand_name,jtr_number,weight,price,shipment_date,status,notes) VALUES(?,?,?,?,?,?,?,?)');$s->execute(array_values($data));$shipmentId=(int)db()->lastInsertId();}
        $itemStmt=db()->prepare('INSERT INTO shipment_items(shipment_id,product_name,brand,quantity,price) VALUES(?,?,?,?,?)');
        foreach(($_POST['item_name']??[]) as $i=>$name){$name=trim($name);if($name==='')continue;$qty=$_POST['item_quantity'][$i]??1;$itemPrice=$_POST['item_price'][$i]??0;if(!is_numeric($qty)||$qty<=0||!is_numeric($itemPrice)||$itemPrice<0)throw new RuntimeException('Invalid item');$itemStmt->execute([$shipmentId,$name,trim($_POST['item_brand'][$i]??''),$qty,$itemPrice]);}
        db()->commit();audit_log($editing?'shipment_updated':'shipment_created','shipment',(int)$shipmentId,['jtr'=>$data['jtr_number'],'customer_id'=>$data['customer_id'],'status'=>$data['status']]);redirect('shipment-receipt.php?id='.$shipmentId.'&new=1');
    }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=$e instanceof PDOException&&$e->getCode()==='23000'?'JTR number already exists, or the customer is invalid.':'Could not save shipment or items.';}
}
$v=$data??($shipment??['customer_id'=>(int)($_GET['customer_id']??0),'shipment_date'=>date('Y-m-d'),'status'=>'turkey_branch']);?>
<h1 class="h3 mb-4"><?=$editing?'Edit Shipment':'Add Shipment'?></h1><div class="card p-4" style="max-width:950px"><?php if(!$customers):?><div class="alert alert-warning">Add a customer before adding a shipment.</div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="row g-3"><div class="col-md-6"><label class="form-label">Customer *</label><select class="form-select" name="customer_id" required><option value="">Choose customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=(int)($v['customer_id']??0)===$c['id']?'selected':''?>><?=e($c['name'].' - '.$c['code'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Shipment Brand Name</label><input class="form-control" name="brand_name" value="<?=e($v['brand_name']??'')?>" placeholder="e.g. SHEIN"></div><div class="col-md-6"><label class="form-label">JTR Number *</label><input class="form-control" name="jtr_number" value="<?=e($v['jtr_number']??'')?>" required></div><div class="col-md-3"><label class="form-label">Weight (KG) *</label><input class="form-control" type="number" min="0" step="0.001" name="weight" value="<?=e($v['weight']??'')?>" required></div><div class="col-md-3"><label class="form-label">Shipment Price ($)</label><input class="form-control" type="number" min="0" step="0.01" name="price" value="<?=e($v['price']??'')?>"></div><div class="col-md-6"><label class="form-label">Date *</label><input class="form-control" type="date" name="shipment_date" value="<?=e($v['shipment_date']??'')?>" required></div><div class="col-md-6"><label class="form-label">Status *</label><select class="form-select" name="status" required><?php foreach(status_labels() as $k=>$label):?><option value="<?=e($k)?>" <?=($v['status']??'')===$k?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div><div class="col-12"><hr><div class="d-flex justify-content-between align-items-center mb-2"><h2 class="h5 mb-0">Shipment Items</h2><button type="button" class="btn btn-sm btn-outline-primary" id="addItem">+ Add Item</button></div><div id="items"><?php foreach(($items??[]) as $item):?><div class="row g-2 item-row mb-2"><div class="col-md-4"><input class="form-control" name="item_name[]" value="<?=e($item['product_name'])?>" placeholder="Product name"></div><div class="col-md-3"><input class="form-control" name="item_brand[]" value="<?=e($item['brand'])?>" placeholder="Brand"></div><div class="col-2"><input class="form-control" type="number" min="0.01" step="0.01" name="item_quantity[]" value="<?=e($item['quantity'])?>" placeholder="Qty"></div><div class="col-2"><input class="form-control" type="number" min="0" step="0.01" name="item_price[]" value="<?=e($item['price'])?>" placeholder="Price ($)"></div><div class="col-1"><button type="button" class="btn btn-outline-danger remove-item">×</button></div></div><?php endforeach;?></div></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="3"><?=e($v['notes']??'')?></textarea></div><div class="col-12"><button class="btn btn-primary">Save & Print Receipt</button> <a class="btn btn-light" href="shipments.php">Cancel</a></div></div></form></div><template id="itemTemplate"><div class="row g-2 item-row mb-2"><div class="col-md-4"><input class="form-control" name="item_name[]" placeholder="Product name"></div><div class="col-md-3"><input class="form-control" name="item_brand[]" placeholder="Brand"></div><div class="col-2"><input class="form-control" type="number" min="0.01" step="0.01" name="item_quantity[]" value="1" placeholder="Qty"></div><div class="col-2"><input class="form-control" type="number" min="0" step="0.01" name="item_price[]" value="0" placeholder="Price ($)"></div><div class="col-1"><button type="button" class="btn btn-outline-danger remove-item">×</button></div></div></template><script>const list=document.querySelector('#items'),tpl=document.querySelector('#itemTemplate');document.querySelector('#addItem').onclick=()=>list.append(tpl.content.cloneNode(true));list.addEventListener('click',e=>{if(e.target.closest('.remove-item'))e.target.closest('.item-row').remove()});if(!list.children.length)document.querySelector('#addItem').click();</script>
